%[text] %[text:anchor:T_3ef5] # Running DICE
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%[text] %[text:anchor:H_5168] ## GAMS results
%[text] Load GAMS results for further comparison:
clear
%[text] The DICE IAM model is essentially controlled by three variables: $\\mu$, $S$, and $\\alpha$. Every other variable can be derived or calculated as a function of those three. Hence, there are two ways of solving DICE: solving for these three control variables, or providing one or more of them as a control value. 
%[text] As a benchmark, we load the results from previous DICE runs:
load GAMSresults.mat tb paris altdam tb_15 tb_20 disc1
%%
%[text] %[text:anchor:H_93cf] ## Optimality Parameters
%[text] Before we start solving the problem, we need to define some optimal parameters. These determine how accurate is the solution and how long is going to take to solve the problem.
StepTolerance = 1e-8; % 1e-9 for an accurate (slower solution)
OptimalTolerance = 1e-6; % 1e-7 for an accurate (slower solution)
ConstraintTolerance = 1e-7;

%starting a thread-pool to compute gradients in parallel
if isempty(gcp('nocreate'))
    parpool threads
end
opts = optimoptions('fmincon',  ...
    'Display', 'off', ...
    "MaxIterations", 999000, ...
    "MaxFunctionEvaluations",999000, ...
    "OptimalityTolerance", OptimalTolerance, ...
    "ConstraintTolerance", ConstraintTolerance, ...
    "StepTolerance", StepTolerance, ...
    "UseParallel", true);
%%
%[text] %[text:anchor:H_64d3] ## Solving the Optimized DICE
%[text] %[text:anchor:H_1a71] ### Solve
%[text] Number of time steps (horizon). Each time step is 5 years
np = 81;
%[text] %[text:anchor:H_5b37] #### **Load the parameters**
params = LoadParams(np);
%[text] %[text:anchor:H_6e6f] #### Create the DICE Problem
prob = diceFunc(np, params);
%[text] %[text:anchor:H_560f] #### Define initial value
x0.MIU = params.miuup(1:np)-eps;
x0.S = 0.25*ones(np, 1);
x0.alpha = [params.a0; 0.4*ones(np-1, 1)];
%[text] %[text:anchor:H_587e] #### Solve the problem
titer = tic;
[sol,fval,exitflag,output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:75db122a] %[output:33150577]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:75db122a] %[output:33150577]
%%
%[text] %[text:anchor:H_6c28] ### Post process the results
%[text] Recover all derived variables such as the Social Cost of Carbon
allVars = recoverAllVars(sol, params);
%[text] %[text:anchor:H_1608] ### Compare the results with GAMS
%[text] Note that all results match the GAMS results from the author with a great degree of accuracy except for the social cost of carbon. This is because in GAMS, this value is approximated differently. The official equation[ proposed by the author](https://www.pnas.org/doi/epdf/10.1073/pnas.1609244114) in:
%[text] $SCC(t) = \\frac{\\partial W}{\\partial E(t)}/\\frac{\\partial W}{\\partial C(t)}$
%[text] In GAMS they compute this using the marginal values returned by the program ( `SCC = -1000*eco2eq.m(t)/(.00001+cc.m(t))` ). Here we take a different approach. First the second term is known, we can easily compute that derivative. Second, the first term can be evaluated as follows:
%[text] 1. Add a small perturbation on E(t)
%[text] 2. Compute W
%[text] 3. Calculate the derivative \
%[text] Then, the easiest way to add a perturbation in E(t) is to add a change in "eland" since it does not affect anything else.
vNames = string(allVars.Properties.VariableNames(1:end-1));
varName = vNames(11); %[control:dropdown:9899]{"position":[11,21]}
doPlot(allVars, varName, tb) %[output:7fcaa43b]
%%
%[text] %[text:anchor:H_0009] ## Constraining Temperature
%[text] %[text:anchor:H_951d] ### Tmax = 2.0 Degrees
%[text] We can enforce a temperature constraint directly when we create the problem
prob = diceFunc(np, params, TempUpperConstraint=2);
%[text] It can be hard to find a solution with a very generic initial condition here. It is easier if we pass the solution from the previous problem.
x0 = sol; %[text:anchor:H_76de]
%[text] Solve the problem as before
titer = tic;
[sol_20,~,exitflag,output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:3257e002] %[output:21dc6518]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:3257e002] %[output:21dc6518]
%%
allVars20 = recoverAllVars(sol_20, params);

vNames = string(allVars20.Properties.VariableNames(1:end-1));
varName = vNames(6); %[control:dropdown:94df]{"position":[11,20]}
doPlot(allVars20, varName, tb_20) %[output:89078fef]
%%
%[text] %[text:anchor:H_1f97] ### Tmax = 1.5 Degrees
%[text] At some point, their assumptions break, and for a low temperature constraint the lower limit on S=0 does not hold anymore. In GAMS they seem to have solve this by setting K\<= instead of K==. It is easier to unbound S
params = LoadParams(np, SLower=-inf);
prob = diceFunc(np, params, TempUpperConstraint=1.5);
%[text] It can be hard to find a solution with a very generic initial condition here. It is easier if we pass the solution from the previous problem.
x0 = sol_20; %[text:anchor:H_76de]
%[text] Solve the problem as before
titer = tic;
[sol_15,~,exitflag,output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:71861d52] %[output:2240b4ec]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:71861d52] %[output:2240b4ec]
%%
allVars15 = recoverAllVars(sol_15, params);

vNames = string(allVars15.Properties.VariableNames(1:end-1));
varName = vNames(6); %[control:dropdown:0395]{"position":[11,20]}
doPlot(allVars15, varName, tb_15) %[output:77a7a3a9]
%%
%[text] %[text:anchor:H_6b5c] ## Change Parameters
%[text] %[text:anchor:H_3013] ### Override Basic parameters (ALTDAM)
%[text] The **`LoadParams`** function allows overriding any parameter. For example, the ALTDAM option in GAMS
params = LoadParams(a2base = 0.01);
prob = diceFunc(np, params);

x0 = sol;
titer = tic;
[sol_altdam,~,exitflag,output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:0d06324c] %[output:2bbad3b1]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:0d06324c] %[output:2bbad3b1]
%%
allVarsALTDAM = recoverAllVars(sol_altdam, params);

vNames = string(allVarsALTDAM.Properties.VariableNames(1:end-1));
varName = vNames(36); %[control:dropdown:57e6]{"position":[11,21]}
doPlot(allVarsALTDAM, varName, altdam) %[output:109f4ffa]
%%
%[text] %[text:anchor:H_9291] ### Override Limits on MIU (PARIS)
%[text] For parameters that cannot be directly overridden, you can always perform the change after. For example:
params = LoadParams(np);

params.miuup(1:5) = min(0.05 + 0.04 * (0:4), 1.00);
params.miuup(6:end) = min(0.05 + 0.04 * (5:np-1) - 0.01 * (1:np-5), 1.00);

prob = diceFunc(np, params);

x0 = sol;
titer = tic;
[sol_paris, ~, exitflag, output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:030bf029] %[output:9d6181a0]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:030bf029] %[output:9d6181a0]
%%
allVarsPARIS = recoverAllVars(sol_paris, params);

vNames = string(allVarsPARIS.Properties.VariableNames(1:end-1));
varName = vNames(31); %[control:dropdown:12c6]{"position":[11,21]}
doPlot(allVarsPARIS, varName, paris) %[output:3a5bd266]
%%
%[text] %[text:anchor:H_9a87] ### Override multiple (DISCOUT 1%)
params = LoadParams(elasmu = 0.001, prstp = 0.01, k0 = 420);

params.RR1 = 1./((1+params.prstp).^(params.tstep*(0:np-1)));
params.RR = params.RR1';

prob = diceFunc(np, params);

x0 = sol;
titer = tic;
[sol_disc1, ~, exitflag, output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:12f9fffd] %[output:953312ba]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:12f9fffd] %[output:953312ba]
%%
allVarsD1 = recoverAllVars(sol_disc1, params);

vNames = string(allVarsD1.Properties.VariableNames(1:end-1));
varName = vNames(31); %[control:dropdown:6a94]{"position":[11,21]}
doPlot(allVarsD1, varName, disc1) %[output:24779a7c]
%%
%[text] %[text:anchor:H_61d2] ## Fix Path for certain variables
%[text] It is also possible to fix the path for like MIU, S, or alpha.
%[text] %[text:anchor:H_1a80] ### Fix MIU
%[text] For example, to fix $\\mu$ to one for the entire period. 
MIUFx = ones(np,1);
%[text] We would do as follows:
params = LoadParams(AlphaUpperBound = Inf, FixSperiod=Inf);
prob = diceFunc(np, params, MIU = MIUFx);

x0 = sol;

titer = tic;
[sol_fx_miu,~,exitflag,output] = solve(prob, x0, Options=opts);
tIteration = toc(titer);

sprintf('Year %d, Iterations = %d, exitFlag = %d, spent = %d secs', ... %[output:group:7a6da656] %[output:7d3ad348]
    2020 + np*params.tstep, output.iterations,double(exitflag),round(tIteration)) %[output:group:7a6da656] %[output:7d3ad348]
%[text] You need to add back those values into the solution to postprocess results
sol_fx_miu.MIU = MIUFx;
%%
allVarsFX = recoverAllVars(sol_fx_miu, params);
vNames = string(allVarsFX.Properties.VariableNames(1:end-1));
varName = vNames(4); %[control:dropdown:4f47]{"position":[11,20]}
doPlot(allVarsFX, varName); %[output:475bf2ee]
%%
function doPlot(allVars, varName, GAMS)

figure
plot(allVars.Year, allVars.(varName), 'LineWidth', 2)
title(varName)
grid on;
if nargin == 3
    hold on;
    plot(allVars.Year, GAMS{varName, :},'ro')
    legend(["MATLAB Estimated", "GAMS"], Location = 'best')
end

end
%[text] 

